  state.ball.x = brick.x - BALL_R + 1;
  state.ball.y = brick.y - BALL_R + 1;
  state.ball.vx = 100; // RIGHT
  state.ball.vy = 100; // DOWN

  const ctx = {
    fillStyle: '',
    fillRect: () => {},
    beginPath: () => {},
