import assert from 'node:assert';
import test from 'node:test';
import { createState, resolveBrickCollision, BALL_R } from '../game/neon.js';

test('D1: Ball should bounce when hitting a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - BALL_R + 1;
  state.ball.vy = 100; 
  resolveBrickCollision(state.ball, brick);
  assert.ok(state.ball.vy < 0, 'Ball should have bounced UP');
});

import assert from 'node:assert';
import test from 'node:test';
import { createState, resolveBrickCollision, collides, BALL_R } from '../game/neon.js';

test('D2: Ball should not stick to the brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - BALL_R + 1; // overlapping
  state.ball.vy = 100; 
  resolveBrickCollision(state.ball, brick);
  assert.ok(!collides(state.ball, brick), 'Ball should be pushed out of the brick');
});

import assert from 'node:assert';
import test from 'node:test';
import { createState, resolveBrickCollision } from '../game/neon.js';

test('D4: Ball should not suffer double inversion at seams', () => {
  const state = createState(1);
  const brick1 = state.bricks[0];
  const brick2 = state.bricks[1];
  state.ball.y = brick1.y + brick1.h / 2;
  state.ball.x = (brick1.x + brick1.w + brick2.x) / 2;
  state.ball.vx = 100;

  // Simulate what happens in the loop:
  resolveBrickCollision(state.ball, brick1);
  resolveBrickCollision(state.ball, brick2);

  assert.ok(state.ball.vx < 0, 'Ball should have bounced LEFT after hitting the seam');
});

import assert from 'node:assert';
import test from 'node:test';
import { createState, resolveBrickCollision, BALL_R } from '../game/neon.js';

test('D5: Ball should bounce on both axes when hitting a corner', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - BALL_R + 1;
  state.ball.y = brick.y - BALL_R + 1;
  state.ball.vx = 100;
  state.ball.vy = 100;
  resolveBrickCollision(state.ball, brick);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, 'Ball should have bounced on both axes');
});

import assert from 'node:assert';
import test from 'node:test';
import { createState, step, ballSpeed } from '../game/neon.js';

test('D3: Ball should not tunnel through bricks at high speed', () => {
  const level = 6;
  const state = createState(level);
  const brick = state.bricks[0];

  // Position ball just above the brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 10; //’t tunnel if we start here and move a lot
  state.ball.vy = ballSpeed(level); 

  // This step will move the ball by ballSpeed * 0.05 = 35.5 pixels.
  // Without sub-stepping, it will jump over the brick (height 20 + 2*R 14 = 34).
  step(state, 0.05);

  assert.strictEqual(brick.alive, false, 'Brick should have been broken');
  assert.ok(state.ball.vy < 0, 'Ball should have bounced');
});
